const queries = [
  // SAP roles
  { q: 'SAP ABAP Developer',               label: 'SAP ABAP Developer'       },
  { q: 'SAP Technical Consultant S4HANA',  label: 'SAP Technical Consultant' },
  { q: 'SAP BTP Integration Developer',    label: 'SAP BTP Integration'      },
  { q: 'SAP BTP CPI Integration Suite',    label: 'SAP BTP CPI'              },
  { q: 'SAP HANA Developer Analytics',     label: 'SAP HANA Developer'       },
  { q: 'SAP Functional Consultant MM SD',  label: 'SAP Functional Consultant'},
  // AI / Data roles
  { q: 'Data Analyst SQL Business Intelligence', label: 'Data Analyst BI'       },
  { q: 'Business Intelligence Analyst SAP',      label: 'BI Analyst SAP'        },
  { q: 'RPA Developer Automation Engineer',      label: 'RPA Automation'        },
  { q: 'AI Automation Specialist workflow',      label: 'AI Automation'         },
  { q: 'AI Integration Engineer API',            label: 'AI Integration'        },
  { q: 'ERP Consultant SAP',                     label: 'ERP Consultant SAP'    },
];
const sapQueries = queries.slice(0, 6);

async function fetchRSS(url) {
  try {
    const resp = await fetch(url, {
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; JobBot/1.0)' },
      signal: AbortSignal.timeout(12000),
    });
    return await resp.text();
  } catch(e) {
    console.log('RSS fetch failed:', url, e.message);
    return '';
  }
}

function parseRSS(xml, source, query) {
  const jobs = [];
  const re = /<item>([\s\S]*?)<\/item>/gi;
  let m;
  while ((m = re.exec(xml)) !== null) {
    const block = m[1];
    const get = (tag) => {
      const r = block.match(new RegExp(`<${tag}[^>]*>(?:<!\\[CDATA\\[([\\s\\S]*?)\\]\\]>|([^<]*))`, 'i'));
      return r ? (r[1] || r[2] || '').trim() : '';
    };
    const title = get('title');
    if (!title || title.length < 4) continue;
    const link = get('link') || get('guid');
    const desc = get('description').replace(/<[^>]+>/g, '').slice(0, 600);
    const company = get('source') || get('author') || '';
    const pubDate = get('pubDate');
    jobs.push({
      id: `${source}-${(link || title).replace(/[^a-z0-9]/gi,'').toLowerCase().slice(0,60)}`,
      title, company, location: '', link,
      description: desc, postedAt: pubDate, source, query,
    });
  }
  return jobs;
}

const all = [];

// ── Indeed RSS — 12 queries ──────────────────────────────────────────────────
for (const { q, label } of queries) {
  const url = `https://www.indeed.com/rss?q=${encodeURIComponent(q)}&l=United+States&sort=date`;
  const xml = await fetchRSS(url);
  if (xml) all.push(...parseRSS(xml, 'Indeed', label));
  await new Promise(r => setTimeout(r, 300));
}

// ── Dice RSS — SAP queries only ──────────────────────────────────────────────
for (const { q, label } of sapQueries) {
  const url = `https://www.dice.com/jobs/rss?q=${encodeURIComponent(q)}&countryCode=US`;
  const xml = await fetchRSS(url);
  if (xml) all.push(...parseRSS(xml, 'Dice', label));
  await new Promise(r => setTimeout(r, 300));
}

// ── We Work Remotely — single feed, keyword-filtered ────────────────────────
const wwrXml = await fetchRSS('https://weworkremotely.com/remote-jobs.rss');
if (wwrXml) {
  const kw = ['sap','abap','automation','ai integration','data analyst','rpa','erp'];
  const wwrJobs = parseRSS(wwrXml, 'WeWorkRemotely', 'Remote Tech')
    .filter(j => kw.some(k => (j.title + j.description).toLowerCase().includes(k)));
  all.push(...wwrJobs);
}

if (all.length === 0) return [{ json: { noJobs: true } }];
return all.map(j => ({ json: j }));

// ── Score + Dedup shared logic ──────────────────────────────────────────────
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.seenJobIds))  staticData.seenJobIds  = [];
if (!Array.isArray(staticData.digestQueue)) staticData.digestQueue = [];

const SEEN_LIMIT   = 5000;
const DIGEST_LIMIT = 300;

const inputItems = $input.all();
if (inputItems.length === 0 || (inputItems.length === 1 && inputItems[0].json.noJobs)) {
  return [{ json: { hasNew: false } }];
}

const jobs = inputItems.map(i => i.json).filter(j => j.title);

const newJobs = [];
for (const job of jobs) {
  const id = (job.id || (job.title + (job.company||'')).replace(/[^a-z0-9]/gi,'').toLowerCase()).slice(0, 80);
  if (staticData.seenJobIds.includes(id)) continue;

  staticData.seenJobIds.push(id);
  if (staticData.seenJobIds.length > SEEN_LIMIT) staticData.seenJobIds.shift();

  // ── Relevance scoring ───────────────────────────────────────────────────
  let score = 0;
  const t = (job.title       || '').toLowerCase();
  const d = (job.description || '').toLowerCase();

  if (/sap|abap|btp|s\/4hana|s4hana|\bhana\b/.test(t))          score += 3;
  if (/\bai\b|automation|data analyst|business intel|\brpa\b|integration/.test(t)) score += 2;
  if (/ricef|odata|n8n|claude|\bbw\b|bw\/4|\bhana\b/.test(d)) score += 2;
  if (job.salary || /\$[\d,]+/.test(d))                           score += 1;
  if (/remote|hybrid/.test(d + t))                                  score += 1;
  if (job.postedAt) {
    try {
      const ageH = (Date.now() - new Date(job.postedAt).getTime()) / 3_600_000;
      if (ageH <= 24) score += 1;
    } catch(_) {}
  }

  const enriched = { ...job, score, id };
  newJobs.push(enriched);

  if (score < 3) {
    staticData.digestQueue.push(enriched);
    if (staticData.digestQueue.length > DIGEST_LIMIT)
      staticData.digestQueue = staticData.digestQueue.slice(-DIGEST_LIMIT);
  }
}

if (newJobs.length === 0) return [{ json: { hasNew: false } }];

// Return only immediate-alert jobs (score >= 3) as items; low-score go to digest only
const alertJobs = newJobs.filter(j => j.score >= 3);
if (alertJobs.length === 0) return [{ json: { hasNew: false } }];

return alertJobs.map(j => ({ json: { ...j, hasNew: true } }));

