sd.digestQueue = [];
queue.sort((a, b) => (b.score || 0) - (a.score || 0));
return [{ json: { hasJobs: true, jobs: queue, count: queue.length } }];

const { jobs, count } = $json;
const timeStr = new Date().toLocaleTimeString('en-US', {
  hour: '2-digit', minute: '2-digit', timeZone: 'America/Los_Angeles'
});

const top   = jobs.slice(0, 10);
const lines = top.map((j, i) => {
  const link = j.link ? `[${j.title}](${j.link})` : j.title;
  return `${i + 1}. ${link} @ *${j.company || 'N/A'}* ⭐${j.score} — ${j.source}`;
});

